import XCTest
@testable import TelexCore

/// English by frequency (`EnglishDominant`, generated by `gen-english --frequency`): a
/// word whose keys compose a valid Vietnamese syllable goes English when English is far
/// more common and the Vietnamese word is rare — also under "Ưu tiên tiếng Việt".
/// Common Vietnamese words and the protect-list stay Vietnamese.
///
/// And ⌫ right after such a restore undoes it: the boundary character goes, the
/// Vietnamese composition comes back, and ending the word unchanged keeps it.
final class FrequencyEnglishTests: XCTestCase {
    /// App defaults: live spell check, context, Vietnamese priority on collisions.
    private func engine() -> TelexEngine {
        var e = TelexEngine()
        e.freeMarking = true; e.liveSpellCheck = true
        e.contextualEnglish = true; e.collisionPrefersVietnamese = true
        return e
    }

    override func tearDown() {
        PersonalLexicon.shared.replace([:])
        super.tearDown()
    }

    private func sentence(_ text: String, personal: Bool = false) -> String {
        var e = engine()
        e.personalLexicon = personal
        var out: [String] = []
        for word in text.split(separator: " ") {
            for ch in word { _ = e.feed(ch) }
            out.append(e.commitText(autoRestore: true))
        }
        return out.joined(separator: " ")
    }

    func testCommonEnglishOverRareVietnamese() {
        for w in ["best", "more", "test", "list", "must", "cost", "rest", "does", "down"] {
            XCTAssertEqual(sentence(w), w, "\(w) alone → English")
        }
    }

    func testCommonVietnameseAndProtectListStay() {
        XCTAssertEqual(sentence("last"), "lát")     // lát nữa: common Vietnamese
        XCTAssertEqual(sentence("there"), "thể")
        XCTAssertEqual(sentence("cos"), "có")
        XCTAssertEqual(sentence("his"), "hí")       // protect-list
        XCTAssertEqual(sentence("been"), "bên")     // protect-list
        XCTAssertEqual(sentence("theme"), "thêm")   // protect-list
    }

    func testMixedSentences() {
        XCTAssertEqual(sentence("tooi test cais nayf roofi"), "tôi test cái này rồi")
        XCTAssertEqual(sentence("check list nhes"), "check list nhé")
        XCTAssertEqual(sentence("best practice laf gif"), "best practice là gì")
        XCTAssertEqual(sentence("cho more option"), "cho more option")
        XCTAssertEqual(sentence("lats nuwax"), "lát nữa")
    }

    func testUppercaseKeepsCase() {
        XCTAssertEqual(sentence("Best"), "Best")
        XCTAssertEqual(sentence("TEST"), "TEST")
    }

    // MARK: - The user's own vocabulary decides first

    func testPersonalVocabularyWinsOverTables() {
        PersonalLexicon.shared.replace(["last": 5, "lát": 1, "bét": 3, "best": 1])
        XCTAssertEqual(sentence("last", personal: true), "last")
        XCTAssertEqual(sentence("best", personal: true), "bét")
        // Flag off: the tables decide.
        XCTAssertEqual(sentence("last"), "lát")
        XCTAssertEqual(sentence("best"), "best")
    }

    func testNoEvidenceOrTieFallsBackToTables() {
        PersonalLexicon.shared.replace(["test": 2, "tét": 2])
        XCTAssertEqual(sentence("best", personal: true), "best")    // no data
        XCTAssertEqual(sentence("last", personal: true), "lát")
        XCTAssertEqual(sentence("test", personal: true), "test")    // tie
    }

    func testLearnsWordsOutsideTheTables() {
        // "lats" is in no table: it composes "lát" and stays Vietnamese until the user
        // has typed "lats" more often than "lát".
        XCTAssertEqual(sentence("lats", personal: true), "lát")
        PersonalLexicon.shared.add("lats")
        XCTAssertEqual(sentence("lats", personal: true), "lats")
        PersonalLexicon.shared.add("lát"); PersonalLexicon.shared.add("lát")
        XCTAssertEqual(sentence("lats", personal: true), "lát")
    }

    func testSingleLetterVietnameseIgnoresPersonalVocabulary() {
        // The word counter skips one-letter words, so "à" is never counted while "af"
        // can be: its English count would always win and "af" could never become "à".
        PersonalLexicon.shared.replace(["af": 22, "as": 3])
        XCTAssertEqual(sentence("af", personal: true), "à")
        XCTAssertEqual(sentence("as", personal: true), "á")
    }

    func testEnglishRunStillRestoresOverPersonalVietnamese() {
        PersonalLexicon.shared.replace(["bên": 50])
        XCTAssertEqual(sentence("been", personal: true), "bên")
        XCTAssertEqual(sentence("it has been", personal: true), "it has been")
    }

    func testUnambiguousWordsIgnoreTheLexicon() {
        // Not a valid syllable ("google") or nothing to change ("cho"): no lookup.
        PersonalLexicon.shared.replace(["gôgle": 9])
        XCTAssertEqual(sentence("google", personal: true), "google")
    }

    // MARK: - ⌫ undoes the restore

    func testBackspaceUndoesRestore() {
        var e = engine()
        for ch in "best" { _ = e.feed(ch) }
        XCTAssertEqual(e.composed, "bét")
        XCTAssertEqual(e.commitBoundary(autoRestore: true),
                       .replace(backspaces: 2, insert: "est"))  // screen: "best"
        XCTAssertFalse(e.canReopenLastCommit, "the screen shows raw keys, not the buffer")
        XCTAssertTrue(e.canUndoLastRestore)
        let undo = e.undoLastRestore()
        XCTAssertEqual(undo?.screen, "best")
        XCTAssertEqual(undo?.composed, "bét")
        XCTAssertEqual(e.composed, "bét")
        // Ending the word unchanged keeps the Vietnamese the user asked for.
        XCTAssertEqual(e.commitBoundary(autoRestore: true), .none)
        XCTAssertFalse(e.canUndoLastRestore)
    }

    func testTypingAfterUndoJudgesTheWordAgain() {
        var e = engine()
        for ch in "best" { _ = e.feed(ch) }
        _ = e.commitBoundary(autoRestore: true)
        _ = e.undoLastRestore()
        _ = e.backspace()                       // "bé"
        _ = e.feed("t")                         // "bét" again, typed fresh
        XCTAssertEqual(e.commitText(autoRestore: true), "best")
    }

    func testInvalidSyllableRestoreIsNotUndoable() {
        var e = engine()
        for ch in "google" { _ = e.feed(ch) }
        XCTAssertEqual(e.commitText(autoRestore: true), "google")
        XCTAssertFalse(e.canUndoLastRestore, "undoing gives no Vietnamese word")
        XCTAssertFalse(e.canReopenLastCommit)
    }

    func testUndoIsOneShotAndNextWordClearsIt() {
        var e = engine()
        for ch in "best" { _ = e.feed(ch) }
        _ = e.commitBoundary(autoRestore: true)
        _ = e.feed("a")                         // a new word starts: nothing to undo
        XCTAssertNil(e.undoLastRestore())
        _ = e.commitBoundary(autoRestore: true)
        XCTAssertFalse(e.canUndoLastRestore)
    }
}
